import { forwardRef, type ButtonHTMLAttributes, type ReactNode } from 'react';

type IconButtonVariant =
  | 'primary'
  | 'secondary'
  | 'tertiary'
  | 'destructive-primary'
  | 'destructive-secondary'
  | 'destructive-tertiary';

type IconButtonSize = 'xs' | 's' | 'm' | 'l' | 'xl';

export type IconButtonProps = {
  variant?: IconButtonVariant;
  size?: IconButtonSize;
  disabled?: boolean;
  loading?: boolean;
  animated?: boolean;
  icon: ReactNode;
  'aria-label': string;
  className?: string;
} & Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'children'>;

function cn(...classes: (string | false | undefined | null)[]) {
  return classes.filter(Boolean).join(' ');
}

const Spinner = () => (
  <svg className="button__spinner-icon" width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden="true">
    <circle cx="8" cy="8" r="6" stroke="currentColor" strokeOpacity="0.25" strokeWidth="2" />
    <path d="M14 8a6 6 0 0 0-6-6" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
  </svg>
);

export const IconButton = forwardRef<HTMLButtonElement, IconButtonProps>(
  (
    {
      variant = 'primary',
      size = 'm',
      disabled = false,
      loading = false,
      animated = false,
      icon,
      className,
      ...props
    },
    ref,
  ) => {
    const classes = cn(
      'icon-button',
      `icon-button--${variant}`,
      `icon-button--${size}`,
      disabled && 'icon-button--disabled',
      loading && 'icon-button--loading',
      className,
    );

    return (
      <button
        ref={ref}
        className={classes}
        disabled={disabled || loading}
        aria-busy={loading}
        {...(animated ? { 'data-icon-button-animate': '' } : {})}
        {...props}
      >
        <span className="icon-button__icon">{icon}</span>
        {loading && (
          <span className="icon-button__spinner">
            <Spinner />
          </span>
        )}
      </button>
    );
  },
);

IconButton.displayName = 'IconButton';

/* -------------------------------------------------------------------------
   Icon Button

   Square button with icon only, no label.
   Shares color variants with Button. Own sizing and animation.

   Variants: primary, secondary, tertiary,
             destructive, destructive-secondary, destructive-tertiary
   Sizes:    xs, sm, default (default), lg, xl
   Animation: icon 360deg rotation on hover (opt-in via data-icon-button-animate)
   ------------------------------------------------------------------------- */

.icon-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  aspect-ratio: 1;
  padding: 0;
  border-radius: 0.625em;
  border: 1px solid transparent;
  font-family: var(--font-family-sans), ui-sans-serif, system-ui, sans-serif;
  line-height: 1;
  cursor: pointer;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
  text-decoration: none;
  transition:
    background-color 0.3s cubic-bezier(0.19, 1, 0.22, 1),
    color 0.3s cubic-bezier(0.19, 1, 0.22, 1),
    border-color 0.3s cubic-bezier(0.19, 1, 0.22, 1),
    scale 0.45s cubic-bezier(0.32, 0.72, 0, 1);
  position: relative;
}

.icon-button:active:not(.icon-button--disabled):not(.icon-button--loading) {
  scale: 0.925;
}

.icon-button:focus-visible {
  outline: var(--ring-width) solid var(--ring);
  outline-offset: var(--ring-offset);
}

@media (hover: hover) and (pointer: fine) and (prefers-reduced-motion: no-preference) {
  .icon-button[data-icon-button-animate]:hover:not(.icon-button--disabled):not(.icon-button--loading) {
    scale: 1.095;
  }
}

@media (prefers-reduced-motion: reduce) {
  .icon-button {
    transition-duration: 0ms;
  }
  .icon-button:active:not(.icon-button--disabled) {
    scale: 1;
  }
}

/* ---- Sizes (square: width = height) ---- */

.icon-button--xs      { width: var(--button-height-xs); height: var(--button-height-xs); font-size: var(--button-font-size-all); }
.icon-button--s      { width: var(--button-height-s); height: var(--button-height-s); font-size: var(--button-font-size-all); }
.icon-button--m { width: var(--button-height-m); height: var(--button-height-m); font-size: var(--button-font-size-all); }
.icon-button--l      { width: var(--button-height-l); height: var(--button-height-l); font-size: var(--button-font-size-all); }
.icon-button--xl      { width: var(--button-height-xl); height: var(--button-height-xl); font-size: var(--button-font-size-all); }

/* ---- Variants (same tokens as Button) ---- */

.icon-button--primary {
  background-color: var(--button-bg-primary);
  color: var(--button-fg-primary);
}
.icon-button--primary:hover:not(.icon-button--disabled) {
  background-color: var(--button-hover-bg-primary);
}
.icon-button--primary:active:not(.icon-button--disabled) {
  background-color: var(--button-pressed-bg-primary);
}

.icon-button--secondary {
  background-color: var(--button-bg-secondary);
  color: var(--button-fg-secondary);
  border-color: var(--button-border-secondary);
}
.icon-button--secondary:hover:not(.icon-button--disabled) {
  background-color: var(--button-hover-bg-secondary);
}
.icon-button--secondary:active:not(.icon-button--disabled) {
  background-color: var(--button-pressed-bg-secondary);
}

.icon-button--tertiary {
  background-color: var(--button-bg-tertiary);
  color: var(--button-fg-tertiary);
}
.icon-button--tertiary:hover:not(.icon-button--disabled) {
  background-color: var(--button-hover-bg-tertiary);
}
.icon-button--tertiary:active:not(.icon-button--disabled) {
  background-color: var(--button-pressed-bg-tertiary);
}

.icon-button--destructive-primary {
  background-color: var(--button-bg-destructive-primary);
  color: var(--button-fg-destructive-primary);
}
.icon-button--destructive-primary:hover:not(.icon-button--disabled) {
  background-color: var(--button-hover-bg-destructive-primary);
}
.icon-button--destructive-primary:active:not(.icon-button--disabled) {
  background-color: var(--button-pressed-bg-destructive-primary);
}

.icon-button--destructive-secondary {
  background-color: var(--button-bg-destructive-secondary);
  color: var(--button-fg-destructive-secondary);
  border-color: var(--button-border-destructive-secondary);
}
.icon-button--destructive-secondary:hover:not(.icon-button--disabled) {
  background-color: var(--button-hover-bg-destructive-secondary);
}
.icon-button--destructive-secondary:active:not(.icon-button--disabled) {
  background-color: var(--button-pressed-bg-destructive-secondary);
}

.icon-button--destructive-tertiary {
  background-color: var(--button-bg-destructive-tertiary);
  color: var(--button-fg-destructive-tertiary);
}
.icon-button--destructive-tertiary:hover:not(.icon-button--disabled) {
  background-color: var(--button-hover-bg-destructive-tertiary);
}
.icon-button--destructive-tertiary:active:not(.icon-button--disabled) {
  background-color: var(--button-pressed-bg-destructive-tertiary);
}

/* ---- States ---- */

.icon-button--disabled {
  color: var(--button-disabled-fg-all);
  cursor: not-allowed;
  pointer-events: none;
}

.icon-button--disabled.icon-button--primary,
.icon-button--disabled.icon-button--secondary,
.icon-button--disabled.icon-button--destructive-primary,
.icon-button--disabled.icon-button--destructive-secondary {
  background-color: var(--muted);
  border-color: transparent;
}

.icon-button--disabled.icon-button--tertiary,
.icon-button--disabled.icon-button--destructive-tertiary {
  background-color: transparent;
  border-color: transparent;
}

.icon-button--loading {
  cursor: wait;
  pointer-events: none;
}

/* ---- Icon ---- */

.icon-button__icon {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 1.25em;
  height: 1.25em;
  will-change: transform;
  transition: rotate 0.5s cubic-bezier(0.19, 1, 0.22, 1);
}

.icon-button__icon svg {
  width: 100%;
  height: 100%;
}

@media (hover: hover) and (pointer: fine) and (prefers-reduced-motion: no-preference) {
  .icon-button[data-icon-button-animate]:is(:hover, :focus-visible) .icon-button__icon,
  [data-hover]:is(:hover, :focus-visible) .icon-button[data-icon-button-animate] .icon-button__icon {
    rotate: 360deg;
    transition: rotate 0.6s 0.05s cubic-bezier(0.19, 1, 0.22, 1);
  }
}

/* ---- Spinner ---- */

.icon-button__spinner {
  display: none;
}

.icon-button--loading .icon-button__icon {
  opacity: 0;
}

.icon-button--loading .icon-button__spinner {
  display: flex;
  position: absolute;
  inset: 0;
  align-items: center;
  justify-content: center;
}
